SELECT /* CommonCodeDetailMapper.validateSortOrderDuplicate */
       COUNT(1)
  FROM COMMON_CODE_DETAIL
 WHERE GROUP_CODE = #{groupCode}
   AND SORT_ORDER = #{sortOrder}


   AND CODE_ID != #{codeId}

SELECT /* CommonCodeDetailMapper.existsCommonDetailCode (그룹 코드 상세 ID 중복 조회) */
       COUNT(1)
  FROM COMMON_CODE_DETAIL
 WHERE GROUP_CODE = #{groupCode}
   AND CODE_ID = #{codeId}

mapper.insert:
INSERT INTO  COMMON_CODE_DETAIL(/* CommonCodeDetailMapper.addCommonDetailCode (그룹 코드 상세 추가) */
            GROUP_CODE
          , CODE_ID
          , CODE_NAME
          , SORT_ORDER
          , USE_YN
          , CREATE_AT
            )
     VALUES (
            #{groupCode}
          , #{codeId}
          , #{codeName}
          , #{sortOrder}
          , #{useYn}
          , CURRENT_TIMESTAMP
            )

mapper.update:
UPDATE /* CommonCodeDetailMapper.updateCommonCodeDetail 그룹 코드 상세 추가 */
       COMMON_CODE_DETAIL
   SET CODE_NAME = #{codeName}
     , SORT_ORDER = #{sortOrder}
     , USE_YN = #{useYn}
     , UPDATE_AT = CURRENT_TIMESTAMP
 WHERE GROUP_CODE = #{groupCode}
   AND CODE_ID =#{codeId}
